# Find all lines with U+2018 (left single) or U+2019 (right single) — these inside double-quoted strings break syntax
problem = []
for i, line in enumerate(content.split('\n'), 1):
    for ch in ['\u2018', '\u2019']:
        if ch in line:
            problem.append((i, line.rstrip(), repr(ch)))

print(f"Lines with U+2018/U+2019: {len(problem)}")
for lineno, line, ch_info in problem:
    print(f"  {lineno}: {line[:100]}")
    print(f"       char: {ch_info}")
